          name: o2.name || null,
          country: o2.country || null,
          city: o2.city || null,
          address: o2.address || null,
          rating: o2.rating || null,
          reviews_count: o2.reviews_count || null,
          website: o2.website || null,
          email: o2.email || null,
          phone: o2.phone || null,
          telegram: o2.telegram || null,
          vk: o2.vk || null,
          instagram: o2.instagram || null,
          whatsapp: o2.whatsapp || null,
          card_url: o2.card_url || null,
          working_hours: o2.working_hours || null,
